import base64
import re
from pathlib import Path

p = Path('whatsapp-score.html')
h = p.read_text(encoding='utf-8')

# Transparent shield-only mark derived from the approved STall logo.
shield_b64 = ''''''

footer = '''<footer class="footer"><div class="footer-inner"><div class="footer-brand"><div class="footer-mark"><img alt="STall" src="data:image/png;base64,%s"></div><div><div class="footer-name">STall</div><div class="footer-micro">THAT'S ALL</div></div></div><div class="footer-copy"><div class="footer-tag">FREE SALON DIGITAL SCORE</div><div class="footer-sub">For Salon Owners. Built to help you get found, trusted and contacted.</div><div class="footer-nav">DISCOVER <span>•</span> CONNECT <span>•</span> GROW</div></div></div></footer>''' % shield_b64

